{
  "intent": "Get Azure Bicep and Container Apps infrastructure design guidance for this Phase 7 static-only architecture, especially private endpoints/DNS, NAT gateway egress, Cosmos MongoDB, and OIDC identity. Do not deploy or inspect user Azure resources.",
  "learn": true
}

{
  "intent": "Discover available Bicep schema lookup commands for verifying resource API schemas and properties without deploying resources.",
  "learn": true
}

{
  "command": "get_azure_bestpractices_ai_app",
  "intent": "Retrieve AI application design guidance for this Bicep-only local-first demo architecture. No deployment or Azure resource inspection.",
  "parameters": {}
}

{
  "command": "get_azure_bestpractices_get",
  "intent": "Retrieve general Azure infrastructure code-generation best practices relevant to Phase 7 Bicep. No deployment.",
  "parameters": {
    "resource": "general",
    "action": "code-generation"
  }
}

{
  "command": "bicepschema_get",
  "intent": "Verify Bicep resource property schemas without deployment.",
  "parameters": {
    "resource-type": "Microsoft.App/containerApps"
  }
}

{
  "command": "bicepschema_get",
  "intent": "Verify Bicep resource property schemas without deployment.",
  "parameters": {
    "resource-type": "Microsoft.App/jobs"
  }
}

{
  "command": "bicepschema_get",
  "intent": "Verify Bicep resource property schemas without deployment.",
  "parameters": {
    "resource-type": "Microsoft.DocumentDB/databaseAccounts"
  }
}

{
  "command": "bicepschema_get",
  "intent": "Verify Bicep resource property schemas without deployment.",
  "parameters": {
    "resource-type": "Microsoft.Network/privateEndpoints"
  }
}

{
  "command": "bicepschema_get",
  "intent": "Verify Bicep resource property schemas without deployment.",
  "parameters": {
    "resource-type": "Microsoft.Search/searchServices"
  }
}

