diff --git a/C:/ubk-repos/product-support-agent/infra/bicep/modules/platform.bicep b/C:/ubk-repos/product-support-agent/infra/bicep/modules/platform.bicep
index 0000000..0000000 100644
--- a/C:/ubk-repos/product-support-agent/infra/bicep/modules/platform.bicep
+++ b/C:/ubk-repos/product-support-agent/infra/bicep/modules/platform.bicep
@@ -1,105 +1,105 @@
 @description('Deployment environment used in resource names.')
 @minLength(3)
 @maxLength(3)
 param environment string

 @description('Two-digit resource instance number.')
 @minLength(2)
 @maxLength(2)
 param instance string

 @description('Azure region for platform resources.')
 param location string

 @description('Resource group name used to create unique service names.')
 @minLength(1)
 @maxLength(90)
 param resourceGroupName string

 @description('Mandatory resource tags.')
 param tags object

 var nameHash = substring(uniqueString(resourceGroup().id), 0, 8)
 var registryName = 'acrpsa${environment}${instance}${nameHash}'
 var keyVaultName = 'kvpsa${environment}cac${instance}${nameHash}'

 resource logAnalyticsWorkspace 'Microsoft.OperationalInsights/workspaces@2023-09-01' = {
   name: 'log-psa-${environment}-cac-${instance}'
   location: location
   tags: tags
   properties: {
     sku: {
       name: 'PerGB2018'
     }
     retentionInDays: 30
     publicNetworkAccessForIngestion: 'Enabled'
     publicNetworkAccessForQuery: 'Enabled'
   }
 }

 resource applicationInsights 'Microsoft.Insights/components@2020-02-02' = {
   name: 'appi-psa-${environment}-cac-${instance}'
   location: location
   tags: tags
   kind: 'web'
   properties: {
     Application_Type: 'web'
     WorkspaceResourceId: logAnalyticsWorkspace.id
     IngestionMode: 'LogAnalytics'
     publicNetworkAccessForIngestion: 'Enabled'
     publicNetworkAccessForQuery: 'Enabled'
   }
 }

 resource keyVault 'Microsoft.KeyVault/vaults@2023-07-01' = {
   name: keyVaultName
   location: location
   tags: tags
   properties: {
     tenantId: subscription().tenantId
     sku: {
       family: 'A'
       name: 'standard'
     }
     enableRbacAuthorization: true
     enabledForDeployment: false
     enabledForDiskEncryption: false
     enabledForTemplateDeployment: false
     publicNetworkAccess: 'Disabled'
     networkAcls: {
       bypass: 'None'
       defaultAction: 'Deny'
     }
   }
 }

 resource registry 'Microsoft.ContainerRegistry/registries@2023-07-01' = {
   name: registryName
   location: location
   tags: tags
   sku: {
     name: 'Premium'
   }
   properties: {
     adminUserEnabled: false
     publicNetworkAccess: 'Disabled'
     anonymousPullEnabled: false
     networkRuleBypassOptions: 'None'
   }
 }

 output logAnalyticsWorkspaceId string = logAnalyticsWorkspace.id
 output logAnalyticsCustomerId string = logAnalyticsWorkspace.properties.customerId
 @secure()
 output logAnalyticsSharedKey string = listKeys(logAnalyticsWorkspace.id, '2023-09-01').primarySharedKey
 output keyVaultId string = keyVault.id
 output keyVaultName string = keyVault.name
 output keyVaultUri string = keyVault.properties.vaultUri
 output registryId string = registry.id
 output registryName string = registry.name
 output registryLoginServer string = registry.properties.loginServer

